SELECT cs.cancer_study_identifier AS study_id, assumeNotNull(r.patient_id) AS patient_id,
upper(trimBoth(JSONExtractString(ifNull(r.metadata, '{}'), 'slide_type'))) AS stored_slide_type, multiIf( JSONExtractBool(ifNull(r.metadata, '{}'), 'is_ihc'), 'IHC', JSONExtractBool(ifNull(r.metadata, '{}'), 'is_hne'), 'H&E', stored_slide_type = 'IHC', 'IHC', stored_slide_type IN ('H&E', 'HE'), 'H&E', stored_slide_type = 'UNKNOWN', 'Unknown', 'Other' ) AS stain_group, JSONExtractBool(ifNull(r.metadata, '{}'), 'can_serve_tiles') AS viewable, multiIf( r.sample_id IS NULL, 'UNMATCHED', JSONExtractString(ifNull(r.metadata, '{}'), 'match_level') IN ('PART', 'UNMATCHED'), JSONExtractString(ifNull(r.metadata, '{}'), 'match_level'), 'BLOCK' ) AS match_level FROM resource_data r INNER JOIN cancer_study cs ON cs.cancer_study_id = r.cancer_study_id PREWHERE r.cancer_study_id IN ( SELECT cancer_study_id FROM cancer_study WHERE cancer_study_identifier IN #{studyId} ) WHERE r.resource_id IN ('WSI_SAMPLE', 'WSI_PATIENT') AND r.type = 'WHOLE_SLIDE_IMAGE' AND r.patient_id IS NOT NULL AND match(JSONExtractString(ifNull(r.metadata, '{}'), 'slide_key'), '^[0-9a-f]{32}$') AND ( (r.sample_id IS NOT NULL AND concat(cs.cancer_study_identifier, '_', r.sample_id) IN (
)) OR (r.sample_id IS NULL AND concat(cs.cancer_study_identifier, '_', assumeNotNull(r.patient_id)) IN ( SELECT patient_unique_id FROM sample_derived WHERE sample_unique_id IN () )) )
AND JSONExtractBool(ifNull(r.metadata, '{}'), 'can_serve_tiles')
AND ( positionCaseInsensitiveUTF8(assumeNotNull(r.patient_id), #{query.search}) > 0 OR positionCaseInsensitiveUTF8(ifNull(r.sample_id, ''), #{query.search}) > 0 )
AND match_level IN #{matchLevel}
